      "text": "ありがとう。"
    },
    {
      "id": 703,
      "text": "野口さん、Machikoさん、こんにちは。"
    },
    {
      "id": 704,
      "text": "こんにちは。"
    },
    {
      "id": 705,
      "text": "私の家での過ごし方は、プロセカをプレイすることです。"
    },
    {
      "id": 706,
      "text": "ありがとう。"
